mod audio;mod game;mod video;use game::Game;
fn main(){let mut captures=vec![];for (typ,handler,state,sprite) in [(10,0x881a,5,0x33),(24,0x8e1f,4,0),(146,0x957c,4,0x66),(38,0xaf7d,3,0),(49,0xafd6,5,0xff),(64,0xa7a9,5,0x7e),(71,0xb4a2,4,0xca),(74,0xb6b2,2,0xd1)] {let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x27]=6;g.memory[0x720]=typ;g.memory[0x520]=state;g.memory[0x500]=sprite;g.memory[0x710]=80;g.memory[0x560]=80;g.memory[0x3b]=6;g.memory[0xd5]=1;g.memory[0x690]=1;let mut samples=vec![];for tick in 0..40 {if g.memory[0x720]!=0 {g.actor_call(handler,0).unwrap();}samples.push(serde_json::json!({"tick":tick,"state":g.memory[0x520],"sprite":g.memory[0x500],"type":g.memory[0x720],"boss_remaining":g.memory[0x3b],"timer":g.memory[0x6d0]}));}captures.push(serde_json::json!({"source_type":typ,"samples":samples}));}println!("{}",serde_json::to_string(&captures).unwrap());}
